// Run this before starting the application

require('dotenv').config();

console.log('=== Environment Validation ===');

// Required variables for all environments
const requiredForAll = ['NODE_ENV', 'PORT'];
const requiredForProduction = ['JWT_SECRET', 'SESSION_SECRET'];

// Check current environment
const nodeEnv = process.env.NODE_ENV || 'development';
console.log(`Current environment: ${nodeEnv}`);

// Validate required variables
const missingVars = [];

requiredForAll.forEach(varName => {
  if (!process.env[varName]) {
    missingVars.push(varName);
  }
});

// Additional checks for production
if (nodeEnv === 'production') {
  console.log('\n=== Production Environment Checks ===');

  // Check production-specific requirements
  requiredForProduction.forEach(varName => {
    if (!process.env[varName]) {
      missingVars.push(varName);
      console.error(`❌ Missing required production variable: ${varName}`);
    } else if (process.env[varName].includes('example') || 
               process.env[varName].includes('placeholder') ||
               process.env[varName].length < 16) {
      console.error(`⚠️  Warning: ${varName} appears to be weak or default value`);
    }
  });

  // Check for test/user data in production
  if (process.env.ENABLE_TEST_USERS === 'true') {
    console.error('❌ CRITICAL: ENABLE_TEST_USERS should be false in production!');
    missingVars.push('ENABLE_TEST_USERS');
  }

  // Check for default ports in production
  if (process.env.PORT === '3000') {
    console.warn('⚠️  Warning: Using default port 3000 in production');
  }
}

// Check for common mistakes
console.log('\n=== Configuration Checks ===');

if (process.env.NODE_ENV === 'production') {
  // Port checks
  const port = parseInt(process.env.PORT || '3000');
  if (port < 1024) {
    console.warn('⚠️  Warning: Ports below 1024 may require root privileges');
  }

  // API prefix checks
  if (!process.env.API_PREFIX || process.env.API_PREFIX === '/') {
    console.warn('⚠️  Warning: API_PREFIX is root or not set in production');
  }
}

// Security checks for all environments
const securityPatterns = ['SECRET', 'KEY', 'PASSWORD', 'TOKEN'];
Object.keys(process.env).forEach(key => {
  securityPatterns.forEach(pattern => {
    if (key.includes(pattern) && 
        (process.env[key].includes('example') || 
         process.env[key].includes('test') ||
         process.env[key].includes('placeholder'))) {
      console.error(`❌ SECURITY: ${key} appears to be a test/placeholder value!`);
    }
  });
});

// Report results
console.log('\n=== Validation Results ===');

if (missingVars.length > 0) {
  console.error(`❌ Missing required environment variables: ${missingVars.join(', ')}`);
  console.error('Please check your .env file or environment configuration.');
  process.exit(1);
} else {
  console.log('✅ All required environment variables are present');

  // Show configuration summary
  console.log('\n=== Configuration Summary ===');
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Port: ${process.env.PORT || '3000'}`);
  console.log(`API Prefix: ${process.env.API_PREFIX || '/api/v1'}`);
  console.log(`Test Users Enabled: ${process.env.ENABLE_TEST_USERS || 'true'}`);

  // Count total environment variables (excluding Node.js internal ones)
  const userEnvVars = Object.keys(process.env).filter(key => 
    !key.startsWith('npm_') && 
    !key.startsWith('NODE_')
  );
  console.log(`Total user environment variables: ${userEnvVars.length}`);

  console.log('\n✅ Environment validation passed!');
  process.exit(0);
}

