// Scanner for hardcoded values that should be environment variables
const fs = require('fs');
const path = require('path');

function scanFile(filePath) {
    console.log(`\n🔍 Scanning file: ${filePath}`);

    try {
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split('\n');

        const patterns = [
            // Ports and URLs
            { 
                regex: /(3000|8080|5000|9000|3306|5432|27017)(?!\d)/g, 
                type: 'Hardcoded Port',
                description: 'Common service ports that should be configurable',
                remediation: 'Use environment variable (e.g., process.env.PORT)'
            },
            { 
                regex: /localhost|127\.0\.0\.1|0\.0\.0\.0/g, 
                type: 'Hardcoded Host',
                description: 'Hardcoded host addresses',
                remediation: 'Use environment variable for host configuration'
            },
            { 
                regex: /http:\/\/(?!localhost)/g, 
                type: 'HTTP URL',
                description: 'Non-localhost HTTP URLs (should be HTTPS in production)',
                remediation: 'Use HTTPS and environment variables for URLs'
            },

            // Credentials and secrets
            { 
                regex: /secret|password|passwd|pwd|key|token|credential/i, 
                type: 'Potential Secret',
                description: 'Words indicating potential secrets',
                remediation: 'Never hardcode secrets - use environment variables or secret managers'
            },
            { 
                regex: /(api[_-]?key|access[_-]?key|secret[_-]?key)=['"][^'"]+['"]/i, 
                type: 'Hardcoded API Key',
                description: 'Hardcoded API/access keys',
                remediation: 'Use environment variables or secret management service'
            },

            // Configuration values
            { 
                regex: /development|production|staging|test/i, 
                type: 'Hardcoded Environment',
                description: 'Hardcoded environment values',
                remediation: 'Use process.env.NODE_ENV or environment variables'
            },
            { 
                regex: /timeout|max|limit|size.*=\s*\d+/i, 
                type: 'Hardcoded Limits',
                description: 'Hardcoded numerical limits',
                remediation: 'Make configurable via environment variables'
            },

            // Database and service URLs
            { 
                regex: /(mongodb|postgres|mysql|redis):\/\//i, 
                type: 'Hardcoded Database URL',
                description: 'Hardcoded database connection strings',
                remediation: 'Use environment variables for database URLs'
            },

            // Email and contact info
            { 
                regex: /@example\.com|@test\.com|admin@|support@/i, 
                type: 'Hardcoded Email/Contact',
                description: 'Hardcoded email addresses',
                remediation: 'Use environment variables or configuration files'
            },

            // Paths and directories
            { 
                regex: /\/var\/log|\/tmp|\/home\/|\/usr\/local|\/etc/i, 
                type: 'Hardcoded Path',
                description: 'Hardcoded file system paths',
                remediation: 'Use environment variables for paths'
            }
        ];

        let findings = [];

        lines.forEach((line, lineNumber) => {
            patterns.forEach(pattern => {
                const matches = line.match(pattern.regex);
                if (matches) {
                    // Skip patterns in comments
                    const commentIndex = line.indexOf('//');
                    const commentInLine = commentIndex !== -1;
                    const patternBeforeComment = commentInLine ? line.substring(0, commentIndex) : line;

                    if (pattern.regex.test(patternBeforeComment)) {
                        findings.push({
                            line: lineNumber + 1,
                            type: pattern.type,
                            matches: matches,
                            lineText: line.trim(),
                            description: pattern.description,
                            remediation: pattern.remediation
                        });
                    }
                }
            });
        });

        if (findings.length > 0) {
            console.log(`Found ${findings.length} potential hardcoded values:\n`);

            findings.forEach((finding, index) => {
                console.log(`${index + 1}. Line ${finding.line}: ${finding.type}`);
                console.log(`   Code: ${finding.lineText}`);
                console.log(`   Matches: ${finding.matches.join(', ')}`);
                console.log(`   Issue: ${finding.description}`);
                console.log(`   Fix: ${finding.remediation}\n`);
            });

            // Group findings by type
            const grouped = {};
            findings.forEach(f => {
                if (!grouped[f.type]) grouped[f.type] = [];
                grouped[f.type].push(f);
            });

            console.log('📊 Summary by type:');
            Object.keys(grouped).forEach(type => {
                console.log(`   ${type}: ${grouped[type].length} occurrences`);
            });

            return findings.length;
        } else {
            console.log('✅ No hardcoded values found that should be environment variables.');
            return 0;
        }

    } catch (error) {
        console.error(`❌ Error scanning file: ${error.message}`);
        return -1;
    }
}

function scanProject() {
    console.log('🔎 Scanning project for hardcoded values...\n');

    // Get all JavaScript files in the project
    const files = [];

    try {
        const allFiles = fs.readdirSync(__dirname);
        allFiles.forEach(file => {
            if (file.endsWith('.js') && file !== 'hardcoded_scanner.js') {
                files.push(path.join(__dirname, file));
            }
        });
    } catch (error) {
        console.error(`Error reading directory: ${error.message}`);
    }

    if (files.length === 0) {
        console.log('No JavaScript files found to scan.');
        return;
    }

    console.log(`Found ${files.length} JavaScript file(s) to scan.\n`);

    let totalFindings = 0;
    files.forEach(file => {
        const findings = scanFile(file);
        if (findings > 0) {
            totalFindings += findings;
        }
    });

    console.log('\n📈 SCAN COMPLETE');
    console.log(`Total files scanned: ${files.length}`);
    console.log(`Total hardcoded values found: ${totalFindings}`);

    if (totalFindings > 0) {
        console.log('\n🚨 RECOMMENDATIONS:');
        console.log('1. Create a .env file (add to .gitignore!)');
        console.log('2. Use process.env.VARIABLE_NAME for configuration');
        console.log('3. Add default values where appropriate: const PORT = process.env.PORT || 3000;');
        console.log('4. Validate environment variables on application startup');
        console.log('5. Use different .env files for different environments (.env.development, .env.production)');
    }
}

