        details: errors.array(),
        validationRules: {
          limit: `Must be between ${config.minPageLimit} and ${config.maxPageLimit}`,
          offset: 'Must be positive integer',
          search: 'Max 100 characters'
        }
      });
    }

    // Use validated and sanitized parameters with defaults
    const { 
      limit = config.defaultPageLimit, 
      offset = 0, 
      search 
    } = req.query;

    // Filter users based on search (simulated - would be database query)
    let filteredUsers = [...config.seedUsers];

    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = filteredUsers.filter(user =>
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const startIndex = parseInt(offset);
    const endIndex = startIndex + parseInt(limit);
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      meta: {
        total: filteredUsers.length,
        returned: paginatedUsers.length,
        page: {
          limit: parseInt(limit),
          offset: parseInt(offset),
          totalPages: Math.ceil(filteredUsers.length / parseInt(limit))
        }
      }
    });
  }
);

// ========== ERROR HANDLING ==========

// 404 Handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });
});

// Global Error Handler
app.use((err, req, res, next) => {
  // Log error with configurable level
  const logMessage = {
    message: err.message,
    stack: config.nodeEnv !== 'production' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
    environment: config.nodeEnv
  };

  if (config.logLevel === 'debug' || config.nodeEnv !== 'production') {
    console.error('Error:', logMessage);
  } else {
    console.error(`Error: ${err.message} at ${req.path}`);
  }

  // CORS errors
  if (err.message.includes('CORS')) {
    return res.status(403).json({
      error: 'CORS policy violation',
      message: config.nodeEnv !== 'production' ? err.message : 'Request origin not allowed'
    });
  }

  // Rate limit errors
  if (err.status === 429) {
    return res.status(429).json({
      error: 'Rate limit exceeded',
      message: 'Too many requests from this IP address'
    });
  }

  // Generic error response
  const errorResponse = {
    error: 'Internal server error',
    timestamp: new Date().toISOString()
  };

  if (config.nodeEnv !== 'production') {
    errorResponse.message = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// ========== SERVER STARTUP ==========

const server = app.listen(config.port, config.host, () => {
  console.log(`🚀 Server started successfully`);
  console.log(`   Environment: ${config.nodeEnv}`);
  console.log(`   URL: http://${config.host}:${config.port}`);
  console.log(`   Health check: http://${config.host}:${config.port}/health`);

  if (config.nodeEnv !== 'production') {
    console.log(`   Config endpoint: http://${config.host}:${config.port}/config`);
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Shutting down...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = { app, config, server };

