require('dotenv').config(); // Load environment variables from .env file

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// ============================================================================
// CONFIGURATION FROM ENVIRONMENT VARIABLES
// ============================================================================

const PORT = parseInt(process.env.PORT, 10) || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const IS_PRODUCTION = NODE_ENV === 'production';

// Security configuration
const CORS_ORIGINS = process.env.CORS_ORIGINS 
  ? process.env.CORS_ORIGINS.split(',').map(origin => origin.trim())
  : IS_PRODUCTION 
    ? [] // Production should explicitly define origins
    : ['http://localhost:3000']; // Default dev origin

const RATE_LIMIT_WINDOW_MS = parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || (15 * 60 * 1000); // 15 minutes default
const RATE_LIMIT_MAX_REQUESTS = parseInt(process.env.RATE_LIMIT_MAX_REQUESTS, 10) || 100;
const BODY_LIMIT = process.env.BODY_LIMIT || '10kb';

// ============================================================================
// VALIDATE CONFIGURATION
// ============================================================================

// Validate required production configuration
if (IS_PRODUCTION) {
  const requiredVars = ['CORS_ORIGINS'];
  const missingVars = requiredVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    console.error(`❌ Missing required environment variables for production: ${missingVars.join(', ')}`);
    console.error('Application will not start in production without these variables.');
    process.exit(1);
  }
}

// ============================================================================
// SECURITY MIDDLEWARE WITH CONFIGURATION
// ============================================================================

// 1. Helmet - Sets various HTTP headers for security
app.use(helmet());

// 2. CORS - Configured from environment
const corsOptions = {
  origin: CORS_ORIGINS,
  optionsSuccessStatus: 200,
  credentials: process.env.CORS_CREDENTIALS === 'true' || false
};
app.use(cors(corsOptions));

// 3. Rate limiting - Configured from environment
const limiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW_MS,
  max: RATE_LIMIT_MAX_REQUESTS,
  message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Body parsing with configured limits
app.use(express.json({ limit: BODY_LIMIT }));
app.use(express.urlencoded({ extended: true, limit: BODY_LIMIT }));

// ============================================================================
// CONFIGURATION LOGGING (Development only)
// ============================================================================

if (!IS_PRODUCTION) {
  console.log('🔧 Application Configuration:');
  console.log(`   Environment: ${NODE_ENV}`);
  console.log(`   Port: ${PORT}`);
  console.log(`   CORS Origins: ${CORS_ORIGINS.join(', ')}`);
  console.log(`   Rate Limit: ${RATE_LIMIT_MAX_REQUESTS} requests per ${RATE_LIMIT_WINDOW_MS / (60 * 1000)} minutes`);
  console.log(`   Body Limit: ${BODY_LIMIT}`);
}

// ============================================================================
// ROUTES
// ============================================================================

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    version: process.env.APP_VERSION || '1.0.0'
  });
});

app.get('/users', (req, res) => {
  // Example data - in real app, these would come from a database
  // Email addresses are example/test data
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ============================================================================
// ERROR HANDLING (Environment-aware)
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  const errorId = Date.now().toString(36) + Math.random().toString(36).substr(2);

  console.error(`Error ID: ${errorId}`, {
    message: err.message,
    stack: !IS_PRODUCTION ? err.stack : undefined, // Only show stack in non-production
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Security: Don't leak error details in production
  const errorResponse = !IS_PRODUCTION
    ? { 
        error: err.message,
        errorId: errorId, // For tracking in logs
        ...(process.env.DEBUG === 'true' && { stack: err.stack })
      }
    : { 
        error: 'Internal server error',
        errorId: errorId // Log reference for support
      };

  res.status(err.status || 500).json(errorResponse);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  console.log(`🚀 Server running in ${NODE_ENV} mode on port ${PORT}`);
});

// ============================================================================
// GRACEFUL SHUTDOWN
// ============================================================================

const shutdown = (signal) => {
  console.log(`\n${signal} received. Graceful shutdown initiated...`);

  server.close(() => {
    console.log('Server closed. Exiting process.');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = { app, server };

