const CORS_MAX_AGE = parseInt(process.env.CORS_MAX_AGE, 10) || 86400; // 24 hours default

// Rate limiting configuration
const RATE_LIMIT_WINDOW_MS = parseInt(process.env.RATE_LIMIT_WINDOW_MS, 10) || (15 * 60 * 1000); // 15 minutes default
const RATE_LIMIT_MAX_REQUESTS = parseInt(process.env.RATE_LIMIT_MAX_REQUESTS, 10) || 100;
const RATE_LIMIT_MESSAGE = process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.';
const RATE_LIMIT_SKIP_SUCCESS_RESPONSES = process.env.RATE_LIMIT_SKIP_SUCCESS_RESPONSES === 'true';

// Request body configuration
const BODY_LIMIT = process.env.BODY_LIMIT || '10kb';

// Logging configuration
const LOG_ERROR_STACK = process.env.LOG_ERROR_STACK === 'true' || !IS_PRODUCTION;
const LOG_IP_ADDRESSES = process.env.LOG_IP_ADDRESSES === 'true';
const LOG_REQUEST_DETAILS = process.env.LOG_REQUEST_DETAILS === 'true' || !IS_PRODUCTION;

// Application metadata
const APP_VERSION = process.env.APP_VERSION || '1.0.0';
const APP_NAME = process.env.APP_NAME || 'Express App';

// ============================================================================
// VALIDATE CONFIGURATION
// ============================================================================

if (IS_PRODUCTION) {
  const requiredEnvVars = [
    'CORS_ORIGINS'
  ];

  const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    console.error('❌ Missing required environment variables for production:');
    missingVars.forEach(varName => {
      console.error(`   - ${varName}`);
    });
    console.error('\nApplication cannot start in production without these variables.');
    console.error('Please set them in your production environment.');
    process.exit(1);
  }
}

// ============================================================================
// CONFIGURATION LOGGING (Development/Verbose mode)
// ============================================================================

if (process.env.VERBOSE_CONFIG === 'true' || !IS_PRODUCTION) {
  console.log('🔧 Application Configuration:');
  console.log(`   Environment: ${NODE_ENV}`);
  console.log(`   Port: ${PORT}`);
  console.log(`   App Name: ${APP_NAME}`);
  console.log(`   App Version: ${APP_VERSION}`);
  console.log(`   CORS Origins: ${CORS_ORIGINS.join(', ')}`);
  console.log(`   CORS Credentials: ${CORS_CREDENTIALS}`);
  console.log(`   CORS Max Age: ${CORS_MAX_AGE}s`);
  console.log(`   Rate Limit: ${RATE_LIMIT_MAX_REQUESTS} requests per ${RATE_LIMIT_WINDOW_MS / (60 * 1000)} minutes`);
  console.log(`   Body Limit: ${BODY_LIMIT}`);
  console.log(`   Log Error Stack: ${LOG_ERROR_STACK}`);
  console.log('');
}

// ============================================================================
// SECURITY MIDDLEWARE WITH CONFIGURATION
// ============================================================================

// 1. Helmet with optional CSP configuration
const helmetConfig = {};
if (process.env.CSP_DIRECTIVES) {
  helmetConfig.contentSecurityPolicy = {
    directives: JSON.parse(process.env.CSP_DIRECTIVES)
  };
}
app.use(helmet(helmetConfig));

// 2. CORS - Fully configurable from environment
const corsOptions = {
  origin: CORS_ORIGINS,
  optionsSuccessStatus: 200,
  credentials: CORS_CREDENTIALS,
  maxAge: CORS_MAX_AGE
};
app.use(cors(corsOptions));

// 3. Rate limiting - Fully configurable
const limiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW_MS,
  max: RATE_LIMIT_MAX_REQUESTS,
  message: RATE_LIMIT_MESSAGE,
  skipSuccessfulRequests: RATE_LIMIT_SKIP_SUCCESS_RESPONSES,
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req) => {
    // Use forwarded IP if behind proxy (configure via environment)
    return process.env.TRUST_PROXY === 'true' 
      ? req.headers['x-forwarded-for'] || req.ip 
      : req.ip;
  }
});
app.use(limiter);

// 4. Body parsing with configurable limits
app.use(express.json({ limit: BODY_LIMIT }));
app.use(express.urlencoded({ extended: true, limit: BODY_LIMIT }));

// ============================================================================
// ROUTES
// ============================================================================

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    app: APP_NAME,
    version: APP_VERSION,
    uptime: process.uptime()
  });
});

app.get('/users', (req, res) => {
  // Example data - in a real app, these would be configurable
  // or come from a database
  const users = process.env.USERS_DATA 
    ? JSON.parse(process.env.USERS_DATA)
    : [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

  res.json(users);
});

// ============================================================================
// ERROR HANDLING (Environment-aware and configurable)
// ============================================================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path,
    method: req.method
  });
});

// Global error handler
app.use((err, req, res, next) => {
  const errorId = Date.now().toString(36) + Math.random().toString(36).substr(2);

  const logDetails = {
    errorId,
    message: err.message,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  };

  if (LOG_ERROR_STACK) {
    logDetails.stack = err.stack;
  }

  if (LOG_IP_ADDRESSES) {
    logDetails.ip = req.ip;
    if (process.env.TRUST_PROXY === 'true') {
      logDetails.forwardedFor = req.headers['x-forwarded-for'];
    }
  }

  if (LOG_REQUEST_DETAILS) {
    logDetails.headers = req.headers;
    logDetails.query = req.query;
    logDetails.params = req.params;
  }

  console.error(`Error ${errorId}:`, logDetails);

  // Response configuration
  const showErrorDetails = process.env.SHOW_ERROR_DETAILS === 'true' || !IS_PRODUCTION;
  const includeErrorId = process.env.INCLUDE_ERROR_ID_IN_RESPONSE === 'true' || !IS_PRODUCTION;

  const errorResponse = {
    error: showErrorDetails ? err.message : 'Internal server error'
  };

  if (includeErrorId) {
    errorResponse.errorId = errorId;
  }

  if (showErrorDetails && process.env.DEBUG === 'true') {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, '0.0.0.0', () => {
  console.log(`🚀 ${APP_NAME} v${APP_VERSION}`);
  console.log(`   Environment: ${NODE_ENV}`);
  console.log(`   Listening on port ${PORT}`);
  console.log(`   CORS enabled for: ${CORS_ORIGINS.length ? CORS_ORIGINS.join(', ') : 'none'}`);
});

// ============================================================================
// GRACEFUL SHUTDOWN (configurable timeout)
// ============================================================================

const SHUTDOWN_TIMEOUT_MS = parseInt(process.env.SHUTDOWN_TIMEOUT_MS, 10) || 10000;

const shutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown (timeout: ${SHUTDOWN_TIMEOUT_MS}ms)...`);

  server.close(() => {
    console.log('✅ Server closed successfully.');
    console.log('👋 Process exiting.');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error(`❌ Could not close connections within ${SHUTDOWN_TIMEOUT_MS}ms, forcing shutdown.`);
    process.exit(1);
  }, SHUTDOWN_TIMEOUT_MS);
};

// Signal handlers
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Uncaught exceptions/rejections
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = { app, server };

