// Secure Express.js application with security best practices
// This version includes security hardening for production use

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// ==================== SECURITY CONFIGURATION ====================

// 1. Security headers using Helmet.js
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS configuration - restrict origins in production
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['https://yourdomain.com']
    : ['http://localhost:3000', 'http://localhost:8080'],
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate limiting - prevent brute force and DDoS attacks
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes'
  },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skipSuccessfulRequests: false,
  keyGenerator: (req) => {
    // Use IP address or user ID if authenticated
    return req.ip || req.headers['x-forwarded-for'] || req.connection.remoteAddress;
  }
});

// Apply rate limiting to all API routes
app.use('/api/', apiLimiter);

// More restrictive limiter for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Only 5 attempts per window
  message: {
    error: 'Too many authentication attempts, please try again later'
  }
});
app.use('/auth/', authLimiter);

// 4. Request logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev', {
  skip: (req, res) => {
    // Skip logging for health checks in production
    return process.env.NODE_ENV === 'production' && req.path === '/health';
  }
}));

// 5. Body parsing with size limits
app.use(express.json({
  limit: '10kb', // Limit JSON body size
  strict: true // Only accept arrays and objects
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
  parameterLimit: 10 // Limit number of parameters
}));

// 6. Remove X-Powered-By header
app.disable('x-powered-by');

// ==================== ROUTES ====================

// Health check endpoint (excluded from some security measures)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    uptime: process.uptime()
  });
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  // Input validation
  const { limit = '10', offset = '0' } = req.query;

  // Parse and validate integers
  const parsedLimit = parseInt(limit, 10);
  const parsedOffset = parseInt(offset, 10);

  // Validation rules
  if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
    return res.status(400).json({ 
      error: 'Invalid limit parameter. Must be between 1 and 100' 
    });
  }

  if (isNaN(parsedOffset) || parsedOffset < 0) {
    return res.status(400).json({ 
      error: 'Invalid offset parameter. Must be a positive integer' 
    });
  }

  // Sanitize output (example data)
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      createdAt: '2023-01-01T00:00:00.000Z'
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      createdAt: '2023-01-02T00:00:00.000Z'
    },
  ];

  // Apply pagination
  const paginatedUsers = users.slice(parsedOffset, parsedOffset + parsedLimit);

  res.json({
    data: paginatedUsers,
    pagination: {
      limit: parsedLimit,
      offset: parsedOffset,
      total: users.length,
      hasMore: parsedOffset + parsedLimit < users.length
    }
  });
});

// ==================== ERROR HANDLING ====================

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Error:`, {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userId: req.user ? req.user.id : 'anonymous'
  });

  // Determine error status
  const statusCode = err.statusCode || err.status || 500;

  // Prepare error response
  const errorResponse = {
    error: 'Internal server error',
    requestId: req.id || Date.now().toString(36) + Math.random().toString(36).substr(2)
  };

  // Include more details in development
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.message = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(statusCode).json(errorResponse);
});

// ==================== SERVER STARTUP ====================

const port = process.env.PORT || 3000;
const host = process.env.HOST || '0.0.0.0';

const server = app.listen(port, host, () => {
  console.log(`🚀 Server started at http://${host}:${port}`);
  console.log(`📊 Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`⏱️  Uptime: ${new Date().toISOString()}`);

  // Log security configuration
  console.log(`🔒 Security features enabled:`);
  console.log(`   • Helmet.js security headers`);
  console.log(`   • CORS with origin restriction`);
  console.log(`   • Rate limiting (API: 100/15min, Auth: 5/15min)`);
  console.log(`   • Request logging`);
  console.log(`   • Body size limits (10kb)`);
  console.log(`   • Input validation`);
});

// ==================== GRACEFUL SHUTDOWN ====================

const shutdown = (signal) => {
  console.log(`\n🛑 ${signal} received, starting graceful shutdown...`);

  server.close(() => {
    console.log('✅ HTTP server closed');
    console.log('👋 Goodbye!');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('⚠️  Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('💥 Uncaught Exception:', err);
  shutdown('UNCAUGHT_EXCEPTION');
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('💥 Unhandled Rejection at:', promise, 'reason:', reason);
  shutdown('UNHANDLED_REJECTION');
});

module.exports = app;

