  const paginatedUsers = users.slice(parsedOffset, parsedOffset + parsedLimit);

  res.json({
    data: paginatedUsers,
    pagination: {
      limit: parsedLimit,
      offset: parsedOffset,
      total: users.length,
      hasMore: parsedOffset + parsedLimit < users.length
    }
  });
});

// ==================== ERROR HANDLING ====================

// 404 handler
app.use((req, res, next) => {
