// Fully Configurable Secure Express.js Application
// All configuration values are externalized via environment variables

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

// ==================== CONFIGURATION ====================
// All values are configurable via environment variables

const config = {
  // Server Configuration
  PORT: process.env.PORT || 3000,
  HOST: process.env.HOST || '0.0.0.0',
  NODE_ENV: process.env.NODE_ENV || 'development',

  // CORS Configuration
  ALLOWED_ORIGINS: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['https://yourdomain.com'],
  DEV_ALLOWED_ORIGINS: process.env.DEV_ALLOWED_ORIGINS
    ? process.env.DEV_ALLOWED_ORIGINS.split(',')
    : ['http://localhost:3000', 'http://localhost:8080'],
  CORS_MAX_AGE: parseInt(process.env.CORS_MAX_AGE) || 86400,
  CORS_METHODS: process.env.CORS_METHODS || 'GET,POST,PUT,DELETE,OPTIONS',
  CORS_ALLOWED_HEADERS: process.env.CORS_ALLOWED_HEADERS || 'Content-Type,Authorization',

  // Rate Limiting Configuration
  RATE_LIMIT_WINDOW_MS: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || (15 * 60 * 1000), // 15 minutes
  RATE_LIMIT_MAX_REQUESTS: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
  AUTH_RATE_LIMIT_MAX: parseInt(process.env.AUTH_RATE_LIMIT_MAX) || 5,

  // Security Headers Configuration
  HSTS_MAX_AGE: parseInt(process.env.HSTS_MAX_AGE) || 31536000, // 1 year
  HSTS_INCLUDE_SUBDOMAINS: process.env.HSTS_INCLUDE_SUBDOMAINS !== 'false',
  HSTS_PRELOAD: process.env.HSTS_PRELOAD !== 'false',

  // Request & Body Limits
  MAX_REQUEST_SIZE: process.env.MAX_REQUEST_SIZE || '10kb',
  MAX_URL_PARAMS: parseInt(process.env.MAX_URL_PARAMS) || 10,

  // Application Limits
  MAX_PAGINATION_LIMIT: parseInt(process.env.MAX_PAGINATION_LIMIT) || 100,
  DEFAULT_PAGE_SIZE: parseInt(process.env.DEFAULT_PAGE_SIZE) || 10,

  // Logging Configuration
  LOG_FORMAT: process.env.LOG_FORMAT || 'dev',
  LOG_SKIP_HEALTH_CHECKS: process.env.LOG_SKIP_HEALTH_CHECKS === 'true',

  // Error Handling
  SHOW_ERROR_DETAILS: process.env.NODE_ENV !== 'production',
  DEFAULT_ERROR_STATUS: parseInt(process.env.DEFAULT_ERROR_STATUS) || 500,

  // Shutdown Configuration
  SHUTDOWN_TIMEOUT_MS: parseInt(process.env.SHUTDOWN_TIMEOUT_MS) || 10000,

  // Application Metadata
  API_VERSION: process.env.API_VERSION || 'v1',
  APP_NAME: process.env.APP_NAME || 'Secure Express API',
};

// Helper function to parse boolean environment variables
const parseBoolean = (value, defaultValue = false) => {
  if (value === undefined || value === null) return defaultValue;
  if (typeof value === 'boolean') return value;
  if (typeof value === 'string') {
    const lower = value.toLowerCase();
    return lower === 'true' || lower === '1' || lower === 'yes';
  }
  return Boolean(value);
};

const app = express();

// ==================== SECURITY CONFIGURATION ====================

// 1. Security headers using Helmet.js with configurable values
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: config.HSTS_MAX_AGE,
    includeSubDomains: config.HSTS_INCLUDE_SUBDOMAINS,
    preload: config.HSTS_PRELOAD
  }
}));

// 2. CORS configuration - fully configurable via environment variables
const corsOptions = {
  origin: config.NODE_ENV === 'production' 
    ? config.ALLOWED_ORIGINS
    : config.DEV_ALLOWED_ORIGINS,
  methods: config.CORS_METHODS.split(','),
  allowedHeaders: config.CORS_ALLOWED_HEADERS.split(','),
  credentials: parseBoolean(process.env.CORS_CREDENTIALS, true),
  maxAge: config.CORS_MAX_AGE
};
app.use(cors(corsOptions));

// 3. Rate limiting - fully configurable
const apiLimiter = rateLimit({
  windowMs: config.RATE_LIMIT_WINDOW_MS,
  max: config.RATE_LIMIT_MAX_REQUESTS,
  message: {
    error: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later'
  },
  standardHeaders: parseBoolean(process.env.RATE_LIMIT_STANDARD_HEADERS, true),
  legacyHeaders: parseBoolean(process.env.RATE_LIMIT_LEGACY_HEADERS, false),
  skipSuccessfulRequests: parseBoolean(process.env.RATE_LIMIT_SKIP_SUCCESSFUL, false),
  keyGenerator: (req) => {
    return req.ip || req.headers['x-forwarded-for'] || req.connection.remoteAddress;
  }
});

// Apply rate limiting to all API routes
app.use('/api/', apiLimiter);

// More restrictive limiter for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: config.RATE_LIMIT_WINDOW_MS,
  max: config.AUTH_RATE_LIMIT_MAX,
  message: {
    error: process.env.AUTH_RATE_LIMIT_MESSAGE || 'Too many authentication attempts, please try again later'
  }
});
app.use('/auth/', authLimiter);

// 4. Request logging - configurable format
const morganFormat = config.NODE_ENV === 'production' ? 'combined' : config.LOG_FORMAT;
const morganSkip = config.LOG_SKIP_HEALTH_CHECKS 
  ? (req, res) => config.NODE_ENV === 'production' && req.path === '/health'
  : undefined;

app.use(morgan(morganFormat, { skip: morganSkip }));

// 5. Body parsing with configurable limits
app.use(express.json({
  limit: config.MAX_REQUEST_SIZE,
  strict: true
}));

app.use(express.urlencoded({
  extended: true,
  limit: config.MAX_REQUEST_SIZE,
  parameterLimit: config.MAX_URL_PARAMS
}));

// 6. Remove X-Powered-By header
app.disable('x-powered-by');

// ==================== ROUTES ====================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.NODE_ENV,
    uptime: process.uptime(),
    version: config.API_VERSION,
    app: config.APP_NAME
  });
});

// Users endpoint with configurable validation
app.get('/users', (req, res) => {
  // Input validation with configurable defaults
  const { 
    limit = config.DEFAULT_PAGE_SIZE.toString(), 
    offset = '0' 
  } = req.query;

  // Parse and validate integers
  const parsedLimit = parseInt(limit, 10);
  const parsedOffset = parseInt(offset, 10);

  // Configurable validation rules
  if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > config.MAX_PAGINATION_LIMIT) {
    return res.status(400).json({ 
      error: `Invalid limit parameter. Must be between 1 and ${config.MAX_PAGINATION_LIMIT}` 
    });
  }

  if (isNaN(parsedOffset) || parsedOffset < 0) {
    return res.status(400).json({ 
      error: 'Invalid offset parameter. Must be a positive integer' 
    });
  }

  // Note: In a real application, this data would come from a database
  // Example data - in production, this would be loaded from a configurable source
  const users = process.env.SAMPLE_USERS 
    ? JSON.parse(process.env.SAMPLE_USERS)
    : [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: '2023-01-01T00:00:00.000Z'
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: '2023-01-02T00:00:00.000Z'
      },
    ];

  // Apply pagination
  const paginatedUsers = users.slice(parsedOffset, parsedOffset + parsedLimit);

  res.json({
    data: paginatedUsers,
    pagination: {
      limit: parsedLimit,
      offset: parsedOffset,
      total: users.length,
      hasMore: parsedOffset + parsedLimit < users.length
    },
    version: config.API_VERSION
  });
});

// ==================== ERROR HANDLING ====================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });
});

// Error handling middleware with configurable error details
app.use((err, req, res, next) => {
  // Log error with configurable level of detail
  const errorDetails = {
    timestamp: new Date().toISOString(),
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    stack: config.SHOW_ERROR_DETAILS ? err.stack : undefined
  };

  console.error(`[${errorDetails.timestamp}] Error:`, errorDetails);

  // Determine error status
  const statusCode = err.statusCode || err.status || config.DEFAULT_ERROR_STATUS;

  // Prepare error response
  const errorResponse = {
    error: 'Internal server error',
    requestId: req.id || Date.now().toString(36) + Math.random().toString(36).substr(2),
    timestamp: errorDetails.timestamp
  };

  // Include more details based on configuration
  if (config.SHOW_ERROR_DETAILS) {
    errorResponse.message = err.message;
    if (config.NODE_ENV !== 'production') {
      errorResponse.stack = err.stack;
    }
  }

  res.status(statusCode).json(errorResponse);
});

// ==================== SERVER STARTUP ====================

const server = app.listen(config.PORT, config.HOST, () => {
  console.log(`🚀 ${config.APP_NAME} started`);
  console.log(`   • Environment: ${config.NODE_ENV}`);
  console.log(`   • Host: http://${config.HOST}:${config.PORT}`);
  console.log(`   • API Version: ${config.API_VERSION}`);
  console.log(`   • Uptime: ${new Date().toISOString()}`);

  // Log security configuration
  console.log(`🔒 Security Configuration:`);
  console.log(`   • Rate Limiting: ${config.RATE_LIMIT_MAX_REQUESTS} requests per ${config.RATE_LIMIT_WINDOW_MS / 60000} minutes`);
  console.log(`   • Auth Rate Limiting: ${config.AUTH_RATE_LIMIT_MAX} attempts`);
  console.log(`   • CORS Origins: ${config.NODE_ENV === 'production' ? config.ALLOWED_ORIGINS.join(', ') : config.DEV_ALLOWED_ORIGINS.join(', ')}`);
  console.log(`   • Request Size Limit: ${config.MAX_REQUEST_SIZE}`);
  console.log(`   • HSTS Max Age: ${config.HSTS_MAX_AGE} seconds`);
});

// ==================== GRACEFUL SHUTDOWN ====================

const shutdown = (signal) => {
  console.log(`\n🛑 ${signal} received, starting graceful shutdown...`);

  server.close(() => {
    console.log('✅ HTTP server closed');
    console.log('👋 Goodbye!');
    process.exit(0);
  });

  // Configurable force shutdown timeout
  setTimeout(() => {
    console.error(`⚠️  Could not close connections in ${config.SHUTDOWN_TIMEOUT_MS}ms, forcefully shutting down`);
    process.exit(1);
  }, config.SHUTDOWN_TIMEOUT_MS);
};

// Signal handlers
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Error handlers
process.on('uncaughtException', (err) => {
  console.error('💥 Uncaught Exception:', err);
  shutdown('UNCAUGHT_EXCEPTION');
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('💥 Unhandled Rejection at:', promise, 'reason:', reason);
  shutdown('UNHANDLED_REJECTION');
});

// Export configuration for testing
module.exports = { app, config };

#!/usr/bin/env node

/**
 * Hardcoded Value Detection Script
 * Scans JavaScript/TypeScript files for hardcoded values that should be environment variables
 */

const fs = require('fs');
const path = require('path');
const { promisify } = require('util');

const readdir = promisify(fs.readdir);
const stat = promisify(fs.stat);
const readFile = promisify(fs.readFile);

// Patterns to detect hardcoded values that should be environment variables
const DETECTION_PATTERNS = [
  // Port numbers
  { 
    pattern: /\b(3000|8080|5432|6379|27017|3306|9200|11211|15672)\b/g,
    description: 'Hardcoded port number',
    category: 'networking',
    severity: 'high'
  },

  // Localhost/domain references
  {
    pattern: /\b(localhost|127\.0\.0\.1|0\.0\.0\.0|example\.com|yourdomain\.com|staging\.|prod\.|dev\.)\b/gi,
    description: 'Hardcoded host/domain name',
    category: 'deployment',
    severity: 'high'
  },

  // Common time values in milliseconds (should be configurable)
  {
    pattern: /\b(1000|5000|10000|30000|60000|300000|600000|900000|1800000|3600000)\b(?!\s*\*\s*\d)/g,
    description: 'Hardcoded timeout/interval value',
    category: 'configuration',
    severity: 'medium'
  },

  // Common limit values
  {
    pattern: /\b(limit:\s*['"`]\d+\s*[kmg]?b['"`]|max(?:imum)?:\s*\d+|size:\s*\d+)/gi,
    description: 'Hardcoded size/limit configuration',
    category: 'configuration',
    severity: 'medium'
  },

  // Database connection strings (partial detection)
  {
    pattern: /(mongodb:\/\/|postgres(?:ql)?:\/\/|mysql:\/\/|redis:\/\/)[^'"\s,;]+/gi,
    description: 'Hardcoded database connection string',
    category: 'security',
    severity: 'critical'
  },

  // API keys/secret patterns (very basic detection)
  {
    pattern: /\b(api[_-]?key|secret[_-]?key|token|password|passwd|pwd)\s*[:=]\s*['"`][^'"`\s]{10,}['"`]/gi,
    description: 'Potential hardcoded credential',
    category: 'security',
    severity: 'critical'
  },

  // Common numeric configurations that should be env vars
  {
    pattern: /\b(port\s*[:=]\s*\d+|timeout\s*[:=]\s*\d+|retries\s*[:=]\s*\d+|attempts\s*[:=]\s*\d+)/gi,
    description: 'Hardcoded numeric configuration',
    category: 'configuration',
    severity: 'medium'
  },

  // File paths that might vary by environment
  {
    pattern: /\b(path\s*[:=]\s*['"`]\/?(?:etc|var|usr|home|tmp|log)\/[^'"`]+['"`])/gi,
    description: 'Hardcoded filesystem path',
    category: 'deployment',
    severity: 'medium'
  },

  // Email/contact information
  {
    pattern: /\b(admin@|support@|contact@|noreply@)[^'"`\s,;]+@[^'"`\s,;]+\.[^'"`\s,;]+/gi,
    description: 'Hardcoded email address',
    category: 'configuration',
    severity: 'low'
  },

  // API endpoint URLs
  {
    pattern: /\b(url\s*[:=]\s*['"`]https?:\/\/[^'"`\s,;]+['"`])/gi,
    description: 'Hardcoded API endpoint URL',
    category: 'configuration',
    severity: 'medium'
  }
];

// Files to exclude from scanning
const EXCLUDE_PATTERNS = [
  /node_modules/,
  /\.git/,
  /\.next/,
  /dist/,
  /build/,
  /coverage/,
  /\.min\.js$/,
  /package-lock\.json$/,
  /yarn\.lock$/,
  /detect_hardcoded\.js$/ // Exclude this file itself
];

// Files to include in scanning
const INCLUDE_EXTENSIONS = [
  '.js',
  '.jsx',
  '.ts',
  '.tsx',
  '.json' // For package.json and config files
];

class HardcodedValueDetector {
  constructor(options = {}) {
    this.options = {
      rootDir: process.cwd(),
      verbose: false,
      ...options
    };

    this.results = {
      critical: [],
      high: [],
      medium: [],
      low: [],
      summary: {
        filesScanned: 0,
        issuesFound: 0,
        byCategory: {},
        bySeverity: {}
      }
    };
  }

  shouldExcludeFile(filePath) {
    return EXCLUDE_PATTERNS.some(pattern => pattern.test(filePath));
  }

  shouldIncludeFile(filePath) {
    const ext = path.extname(filePath).toLowerCase();
    return INCLUDE_EXTENSIONS.includes(ext);
  }

  async scanFile(filePath) {
    if (this.shouldExcludeFile(filePath) || !this.shouldIncludeFile(filePath)) {
      return;
    }

    try {
      const content = await readFile(filePath, 'utf8');
      const relativePath = path.relative(this.options.rootDir, filePath);

      for (const detector of DETECTION_PATTERNS) {
        const matches = [];
        let match;

        // Reset regex lastIndex
        detector.pattern.lastIndex = 0;

        while ((match = detector.pattern.exec(content)) !== null) {
          // Get line number
          const linesUpToMatch = content.substring(0, match.index).split('\n');
          const lineNumber = linesUpToMatch.length;
          const lineContent = linesUpToMatch[linesUpToMatch.length - 1] + 
                            match[0] + 
                            content.substring(match.index + match[0].length).split('\n')[0];

          matches.push({
            match: match[0],
            line: lineNumber,
            lineContent: lineContent.trim()
          });
        }

        if (matches.length > 0) {
          this.addResult(filePath, relativePath, detector, matches);
        }
      }

      this.results.summary.filesScanned++;

    } catch (error) {
      if (this.options.verbose) {
        console.error(`Error scanning ${filePath}:`, error.message);
      }
    }
  }

  addResult(filePath, relativePath, detector, matches) {
    const result = {
      file: relativePath,
      description: detector.description,
      category: detector.category,
      severity: detector.severity,
      matches: matches.slice(0, 5), // Show first 5 matches only
      totalMatches: matches.length
    };

    // Add to appropriate severity array
    this.results[result.severity].push(result);

    // Update summary
    this.results.summary.issuesFound++;

    if (!this.results.summary.byCategory[result.category]) {
      this.results.summary.byCategory[result.category] = 0;
    }
    this.results.summary.byCategory[result.category]++;

    if (!this.results.summary.bySeverity[result.severity]) {
      this.results.summary.bySeverity[result.severity] = 0;
    }
    this.results.summary.bySeverity[result.severity]++;
  }

  async scanDirectory(dirPath) {
    try {
      const items = await readdir(dirPath);

      for (const item of items) {
        const fullPath = path.join(dirPath, item);
        const stats = await stat(fullPath);

        if (stats.isDirectory()) {
          await this.scanDirectory(fullPath);
        } else if (stats.isFile()) {
          await this.scanFile(fullPath);
        }
      }
    } catch (error) {
      if (this.options.verbose) {
        console.error(`Error scanning directory ${dirPath}:`, error.message);
      }
    }
  }

  printResults() {
    console.log('\n🔍 Hardcoded Value Detection Report\n');
    console.log('='.repeat(80));

    // Print by severity
    const severities = ['critical', 'high', 'medium', 'low'];

    for (const severity of severities) {
      const issues = this.results[severity];
      if (issues.length === 0) continue;

      console.log(`\n${severity.toUpperCase()} Severity Issues (${issues.length}):`);
      console.log('-'.repeat(80));

      for (const issue of issues) {
        console.log(`\n📄 ${issue.file}`);
        console.log(`   📝 ${issue.description}`);
        console.log(`   🏷️  Category: ${issue.category}`);
        console.log(`   ⚠️  Matches: ${issue.totalMatches} found`);

        // Show first few matches
        for (const match of issue.matches) {
