// app_final_secure.js - Production-ready secure version with config module
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

// Use centralized configuration module
const config = require('./config');

const app = express();

// ====================
// SECURITY MIDDLEWARE
// ====================

// Set security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));

// Configure CORS using environment-specific settings
app.use(cors({
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps, curl, etc.)
    if (!origin) return callback(null, true);

    if (config.nodeEnv === 'development') {
      // In development, allow localhost and all origins for testing
      return callback(null, true);
    }

    // In production, check against allowed origins
    if (config.cors.allowedOrigins.includes(origin)) {
      return callback(null, true);
    } else {
      const msg = `The CORS policy for this site does not allow access from the specified Origin: ${origin}`;
      return callback(new Error(msg), false);
    }
  },
  credentials: config.cors.credentials,
  exposedHeaders: ['X-RateLimit-Limit', 'X-RateLimit-Remaining', 'X-RateLimit-Reset']
}));

// Rate limiting for API routes
const apiLimiter = rateLimit({
  windowMs: config.rateLimit.windowMs,
  max: config.rateLimit.max,
  message: config.rateLimit.message,
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health checks in some cases
    return req.path === '/health' && req.method === 'GET';
  }
});

// Apply rate limiting to API routes
app.use('/api/', apiLimiter);

// Additional strict rate limiting for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 attempts per windowMs
  message: 'Too many login attempts, please try again later.',
  skipSuccessfulRequests: true
});

// Apply to auth routes (if they exist)
// app.use('/api/auth/', authLimiter);

// ====================
// REQUEST PROCESSING
// ====================

// Body parsing with configured limits
app.use(express.json({ 
  limit: config.bodyParser.jsonLimit,
  verify: (req, res, buf) => {
    // Store raw body for signature verification if needed
    req.rawBody = buf;
  }
}));

app.use(express.urlencoded({ 
  extended: config.bodyParser.extended, 
  limit: config.bodyParser.urlencodedLimit 
}));

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();

  // Log after response is sent
  res.on('finish', () => {
    const duration = Date.now() - start;
    const logMessage = `${new Date().toISOString()} - ${req.method} ${req.originalUrl} - ${res.statusCode} - ${duration}ms`;

    if (res.statusCode >= 400) {
      console.error(logMessage);
    } else if (config.debug) {
      console.log(logMessage);
    }
  });

  next();
});

// ====================
// ROUTES
// ====================

// Health endpoint - minimal information exposed
app.get('/health', (req, res) => {
  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    app: config.app.name,
    version: config.app.version,
    environment: config.nodeEnv
  };

  // In production, add more comprehensive health checks
  if (config.nodeEnv === 'production') {
    // Check database connection, external services, etc.
    healthData.services = {
      database: 'connected', // Would actually check DB
      cache: 'connected'     // Would actually check cache
    };
  }

  res.set('Cache-Control', 'no-store'); // Don't cache health checks
  res.json(healthData);
});

// Users endpoint with proper validation
app.get('/users', 
  [
    // Validate query parameters
    body('limit').optional().isInt({ 
      min: 1, 
      max: config.api.maxLimit 
    }).withMessage(`Limit must be between 1 and ${config.api.maxLimit}`),

    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),

    body('sort').optional().isIn(['asc', 'desc', 'name', 'email']).withMessage('Invalid sort value')
  ],
  (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }

    // Parse query parameters with defaults
    const limit = parseInt(req.query.limit) || config.api.defaultLimit;
    const page = parseInt(req.query.page) || 1;
    const offset = (page - 1) * limit;

    // In a real application, this would come from a database
    // For demo purposes, return static data
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        role: 'user',
        createdAt: '2023-01-15T10:30:00Z'
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        role: 'admin',
        createdAt: '2023-02-20T14:45:00Z'
      }
    ];

    // Apply pagination (in real app, this would be done in DB query)
    const paginatedUsers = users.slice(offset, offset + limit);

    // Construct response with metadata
    const response = {
      data: paginatedUsers,
      meta: {
        page,
        limit,
        total: users.length,
        totalPages: Math.ceil(users.length / limit),
        hasNextPage: offset + limit < users.length,
        hasPrevPage: page > 1
      }
    };

    // Add rate limit headers to response
    const rateLimitRemaining = res.get('RateLimit-Remaining');
    if (rateLimitRemaining) {
      response.meta.rateLimitRemaining = parseInt(rateLimitRemaining);
    }

    res.json(response);
});

// ====================
// ERROR HANDLING
// ====================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested resource ${req.method} ${req.originalUrl} was not found`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log the error
  console.error(`${new Date().toISOString()} - ERROR:`, {
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    userAgent: req.get('User-Agent')
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Prepare error response based on environment
  let errorResponse;

  if (config.nodeEnv === 'production') {
    // In production, don't expose stack traces or internal details
    errorResponse = {
      error: 'Internal Server Error',
      message: 'An unexpected error occurred',
      timestamp: new Date().toISOString(),
      requestId: req.id || Math.random().toString(36).substring(7)
    };

    // For known error types, provide more specific messages
    if (err.name === 'ValidationError') {
      errorResponse.error = 'Validation Error';
      errorResponse.message = 'Invalid input data';
    } else if (err.name === 'UnauthorizedError') {
      errorResponse.error = 'Unauthorized';
      errorResponse.message = 'Authentication required';
    }
  } else {
    // In development, provide detailed error information
    errorResponse = {
      error: err.name || 'Error',
      message: err.message,
      stack: err.stack,
      timestamp: new Date().toISOString()
    };
  }

  res.status(statusCode).json(errorResponse);
});

