// Secure Express application with configuration via environment variables
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// Configuration from environment variables with defaults
const CONFIG = {
  PORT: process.env.PORT || 3000,
  NODE_ENV: process.env.NODE_ENV || 'development',

  // Rate limiting configuration
  RATE_LIMIT_WINDOW_MS: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || (15 * 60 * 1000), // 15 minutes
  RATE_LIMIT_MAX_REQUESTS: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
  RATE_LIMIT_MESSAGE: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.',

  // Pagination limits
  MAX_PAGINATION_LIMIT: parseInt(process.env.MAX_PAGINATION_LIMIT) || 100,
  DEFAULT_PAGINATION_LIMIT: parseInt(process.env.DEFAULT_PAGINATION_LIMIT) || 10,

  // Security settings
  ENABLE_RATE_LIMITING: process.env.ENABLE_RATE_LIMITING !== 'false', // Default true
  ENABLE_HELMET: process.env.ENABLE_HELMET !== 'false', // Default true

  // Application settings
  APP_NAME: process.env.APP_NAME || 'Secure Node App',
  APP_VERSION: process.env.APP_VERSION || '1.0.0',
};

// Security middleware (conditional based on config)
if (CONFIG.ENABLE_HELMET) {
  app.use(helmet());
}

// Rate limiting (conditional based on config)
if (CONFIG.ENABLE_RATE_LIMITING) {
  const limiter = rateLimit({
    windowMs: CONFIG.RATE_LIMIT_WINDOW_MS,
    max: CONFIG.RATE_LIMIT_MAX_REQUESTS,
    message: CONFIG.RATE_LIMIT_MESSAGE,
  });
  app.use(limiter);
}

// Parse JSON bodies
app.use(express.json());

// Input validation middleware
app.use((req, res, next) => {
  // Basic input sanitization
  const sanitizeInput = (input) => {
    if (typeof input === 'string') {
      return input.replace(/[<>]/g, ''); // Basic XSS protection
    }
    return input;
  };

  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      req.query[key] = sanitizeInput(req.query[key]);
    });
  }

  // Sanitize body parameters
  if (req.body && typeof req.body === 'object') {
    Object.keys(req.body).forEach(key => {
      req.body[key] = sanitizeInput(req.body[key]);
    });
  }

  next();
});

// Health check endpoint with app info
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: CONFIG.NODE_ENV,
    app: {
      name: CONFIG.APP_NAME,
      version: CONFIG.APP_VERSION,
    },
    config: {
      rateLimitingEnabled: CONFIG.ENABLE_RATE_LIMITING,
      helmetEnabled: CONFIG.ENABLE_HELMET,
    }
  });
});

// Users endpoint with configurable pagination
app.get('/users', (req, res) => {
  const { limit, offset } = req.query;

  // Validate numeric parameters using config
  const validatedLimit = Math.min(
    parseInt(limit) || CONFIG.DEFAULT_PAGINATION_LIMIT, 
    CONFIG.MAX_PAGINATION_LIMIT
  );
  const validatedOffset = Math.max(parseInt(offset) || 0, 0);

  // Mock user data - consider moving to a database or external config
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Note: In production, this data would come from a database
  // The emails are example placeholders and could be configurable
  // via environment variables if needed for different environments

  // Apply pagination
  const paginatedUsers = users.slice(validatedOffset, validatedOffset + validatedLimit);

  res.json({
    data: paginatedUsers,
    pagination: {
      limit: validatedLimit,
      offset: validatedOffset,
      total: users.length,
      maxLimit: CONFIG.MAX_PAGINATION_LIMIT
    }
  });
});

// Config endpoint (development only - disable in production)
if (CONFIG.NODE_ENV !== 'production') {
  app.get('/config', (req, res) => {
    // Return safe config values (excluding any sensitive data)
    const safeConfig = {
      ...CONFIG,
      // Omit any potentially sensitive values
      RATE_LIMIT_MESSAGE: '[REDACTED IN PRODUCTION]'
    };
    res.json(safeConfig);
  });
}

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose stack traces in production
  const errorResponse = {
    error: 'Internal Server Error',
    message: CONFIG.NODE_ENV === 'production' 
      ? 'An unexpected error occurred' 
      : err.message
  };

  res.status(500).json(errorResponse);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    timestamp: new Date().toISOString()
  });
});

app.listen(CONFIG.PORT, () => {
  console.log(`${CONFIG.APP_NAME} v${CONFIG.APP_VERSION}`);
  console.log(`Server running on port ${CONFIG.PORT} in ${CONFIG.NODE_ENV} mode`);
  console.log(`Rate limiting: ${CONFIG.ENABLE_RATE_LIMITING ? 'Enabled' : 'Disabled'}`);
  console.log(`Security headers: ${CONFIG.ENABLE_HELMET ? 'Enabled' : 'Disabled'}`);
});

module.exports = { app, CONFIG };

