// Fully configurable version with all values externalized
// All configuration comes from environment variables

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const path = require('path');
require('dotenv').config();

// Configuration helper functions
const getConfig = {
  // Server configuration
  port: () => parseInt(process.env.PORT) || 3000,
  nodeEnv: () => process.env.NODE_ENV || 'development',
  appVersion: () => process.env.APP_VERSION || 'unknown',

  // Security configuration
  securityEnabled: () => process.env.SECURITY_ENABLED !== 'false',

  // CSP configuration
  cspDirectives: () => {
    try {
      return process.env.CSP_DIRECTIVES ? 
        JSON.parse(process.env.CSP_DIRECTIVES) :
        {
          defaultSrc: ["'self'"],
          styleSrc: ["'self'"],
          scriptSrc: ["'self'"]
        };
    } catch (e) {
      console.warn('Invalid CSP_DIRECTIVES JSON, using defaults');
      return {
        defaultSrc: ["'self'"],
        styleSrc: ["'self'"],
        scriptSrc: ["'self'"]
      };
    }
  },

  // HSTS configuration
  hstsConfig: () => ({
    maxAge: parseInt(process.env.HSTS_MAX_AGE) || 31536000,
    includeSubDomains: process.env.HSTS_INCLUDE_SUBDOMAINS !== 'false',
    preload: process.env.HSTS_PRELOAD === 'true'
  }),

  // CORS configuration
  corsConfig: () => {
    const origins = process.env.CORS_ALLOWED_ORIGINS ? 
      process.env.CORS_ALLOWED_ORIGINS.split(',').map(o => o.trim()) : 
      [];

    const methods = process.env.CORS_ALLOWED_METHODS ?
      process.env.CORS_ALLOWED_METHODS.split(',').map(m => m.trim().toUpperCase()) :
      ['GET', 'POST'];

    const headers = process.env.CORS_ALLOWED_HEADERS ?
      process.env.CORS_ALLOWED_HEADERS.split(',').map(h => h.trim()) :
      ['Content-Type', 'Authorization'];

    return {
      origin: origins.length > 0 ? origins : false, // false = no CORS
      methods,
      allowedHeaders: headers,
      credentials: process.env.CORS_CREDENTIALS === 'true'
    };
  },

  // Rate limiting configuration
  rateLimitConfig: () => ({
    windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || (15 * 60 * 1000),
    max: parseInt(process.env.RATE_LIMIT_MAX) || 100,
    message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false
  }),

  // API Key validation
  apiKey: () => process.env.API_KEY,

  // Logging configuration
  logLevel: () => process.env.LOG_LEVEL || 'info',
  logErrors: () => process.env.LOG_ERRORS !== 'false',

  // Feature flags
  features: () => ({
    usersEndpoint: process.env.FEATURE_USERS_ENDPOINT !== 'false',
    healthEndpoint: process.env.FEATURE_HEALTH_ENDPOINT !== 'false',
    authentication: process.env.FEATURE_AUTHENTICATION !== 'false'
  })
};

const app = express();

// Security middleware - only if enabled
if (getConfig.securityEnabled()) {
  // Helmet security headers
  app.use(helmet({
    contentSecurityPolicy: {
      directives: getConfig.cspDirectives()
    },
    hsts: getConfig.hstsConfig()
  }));

  // CORS - configurable
  const corsConfig = getConfig.corsConfig();
  if (corsConfig.origin !== false) {
    app.use(cors(corsConfig));
  }

  // Rate limiting
  app.use(rateLimit(getConfig.rateLimitConfig()));
}

// Request logging middleware
app.use((req, res, next) => {
  if (getConfig.logLevel() === 'debug') {
    console.log(`${new Date().toISOString()} ${req.method} ${req.path} - ${req.ip}`);
  }
  next();
});

// Authentication middleware - configurable
const createAuthMiddleware = () => {
  const apiKey = getConfig.apiKey();
  const authEnabled = getConfig.features().authentication && apiKey;

  if (!authEnabled) {
    console.warn('Authentication disabled: No API_KEY configured');
    return (req, res, next) => next();
  }

  return (req, res, next) => {
    const clientApiKey = req.headers['x-api-key'] || req.query.apiKey;

    if (!clientApiKey) {
      return res.status(401).json({ error: 'API key required' });
    }

    if (clientApiKey !== apiKey) {
      return res.status(403).json({ error: 'Invalid API key' });
    }

    next();
  };
};

const authenticate = createAuthMiddleware();

// Health endpoint - configurable
if (getConfig.features().healthEndpoint) {
  app.get('/health', (req, res) => {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      version: getConfig.appVersion(),
      environment: getConfig.nodeEnv(),
      security: getConfig.securityEnabled() ? 'enabled' : 'disabled'
    });
  });
}

// Users endpoint - configurable with authentication
if (getConfig.features().usersEndpoint) {
  app.get('/users', authenticate, (req, res) => {
    // In production, this would come from a database
    // Configurable via environment variable for test data
    const usersData = process.env.USERS_DATA ?
      JSON.parse(process.env.USERS_DATA) :
      [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' }
      ];

    res.json(usersData);
  });
}

// Configuration endpoint (protected)
app.get('/config', authenticate, (req, res) => {
  // Return non-sensitive configuration for debugging
  res.json({
    environment: getConfig.nodeEnv(),
    version: getConfig.appVersion(),
    features: getConfig.features(),
    security: {
      enabled: getConfig.securityEnabled(),
      rateLimit: getConfig.rateLimitConfig().max,
      cors: getConfig.corsConfig().origin !== false
    }
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  if (getConfig.logErrors()) {
    console.error('Error:', {
      timestamp: new Date().toISOString(),
      path: req.path,
      method: req.method,
      ip: req.ip,
      error: err.message,
      stack: getConfig.nodeEnv() === 'development' ? err.stack : undefined
    });
  }

  const errorResponse = {
    error: 'Internal server error'
  };

  if (getConfig.nodeEnv() === 'development') {
    errorResponse.details = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(500).json(errorResponse);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path,
    method: req.method
  });
});

// Start server
const port = getConfig.port();
app.listen(port, () => {
  console.log(`
🚀 Server Configuration:
   Port: ${port}
   Environment: ${getConfig.nodeEnv()}
   Version: ${getConfig.appVersion()}
   Security: ${getConfig.securityEnabled() ? '✅ Enabled' : '❌ Disabled'}
   Authentication: ${getConfig.apiKey() ? '✅ Configured' : '❌ Not configured'}
   Features: ${JSON.stringify(getConfig.features())}

📡 Server running: http://localhost:${port}
  `);
});

module.exports = {
  app,
  getConfig // Export for testing
};

#!/usr/bin/env node
// Configuration validator for environment variables
// Run: node config-validator.js

const fs = require('fs');
const path = require('path');

// Required configuration for different environments
const requirements = {
  development: {
    required: ['NODE_ENV'],
    recommended: ['PORT', 'LOG_LEVEL'],
    security: {
      warnIfMissing: ['API_KEY'],
      warnIfDefault: ['API_KEY=development_key']
    }
  },

  testing: {
    required: ['NODE_ENV', 'API_KEY'],
    recommended: ['PORT', 'LOG_LEVEL'],
    security: {
      warnIfMissing: [],
      warnIfTestValues: ['API_KEY=test_key', 'DB_PASSWORD=test']
    }
  },

  staging: {
    required: ['NODE_ENV', 'API_KEY', 'DB_HOST', 'DB_PASSWORD'],
    recommended: ['PORT', 'LOG_LEVEL', 'CORS_ALLOWED_ORIGINS'],
    security: {
      warnIfMissing: ['HSTS_MAX_AGE', 'RATE_LIMIT_MAX'],
      warnIfDefault: ['API_KEY=staging_key']
    }
  },

  production: {
    required: [
      'NODE_ENV',
      'API_KEY',
      'DB_HOST',
      'DB_PASSWORD',
      'CORS_ALLOWED_ORIGINS'
    ],
    recommended: [
      'PORT',
      'LOG_LEVEL',
      'HSTS_MAX_AGE',
      'RATE_LIMIT_MAX',
      'SECURITY_ENABLED'
    ],
    security: {
      warnIfMissing: [],
      critical: [
        'NODE_ENV=production',
        'SECURITY_ENABLED=true',
        'CORS_ALLOWED_ORIGINS'  // Must be set to specific domains
      ]
    }
  }
};

// Common security checks
const securityPatterns = {
  weakPasswords: [
    /password/i,
    /123456/,
    /admin/,
    /secret/i,
    /test/i,
    /changeme/i
  ],

  testPatterns: [
    /test_/i,
    /dev_/i,
    /staging_/i,
    /example\./,
    /localhost/,
    /127\.0\.0\.1/
  ],

  sensitiveInLogs: [
    /password/i,
    /secret/i,
    /key/i,
    /token/i,
    /credential/i
  ]
};

function validateConfiguration() {
  console.log('🔍 Configuration Validator\n');

  // Check if .env file exists
  const envPath = path.join(process.cwd(), '.env');
  if (!fs.existsSync(envPath)) {
    console.warn('⚠️  No .env file found. Using process environment variables.');
  } else {
    console.log('✅ .env file found');
  }

  const env = process.env;
  const nodeEnv = env.NODE_ENV || 'development';

  console.log(`📋 Environment: ${nodeEnv.toUpperCase()}\n`);

  // Get requirements for current environment
  const envRequirements = requirements[nodeEnv] || requirements.development;

  // Check required variables
  console.log('🔴 REQUIRED VARIABLES:');
  let missingRequired = [];
  envRequirements.required.forEach(variable => {
    if (!env[variable]) {
      missingRequired.push(variable);
      console.log(`  ❌ ${variable} - MISSING`);
    } else {
      console.log(`  ✅ ${variable} - Set`);
    }
  });

  // Check recommended variables
  console.log('\n🟡 RECOMMENDED VARIABLES:');
  envRequirements.recommended.forEach(variable => {
    if (!env[variable]) {
      console.log(`  ⚠️  ${variable} - Not set (recommended)`);
    } else {
      console.log(`  ✅ ${variable} - Set`);
    }
  });

  // Security checks
  console.log('\n🔒 SECURITY CHECKS:');

  // Check for weak passwords/keys
  Object.keys(env).forEach(key => {
    const value = env[key];

    // Check for weak values
    securityPatterns.weakPasswords.forEach(pattern => {
      if (pattern.test(value)) {
        console.log(`  ⚠️  ${key} - Contains potentially weak value`);
      }
    });

    // Check for test patterns in production
    if (nodeEnv === 'production') {
      securityPatterns.testPatterns.forEach(pattern => {
        if (pattern.test(value)) {
          console.log(`  ⚠️  ${key} - Contains test pattern in production`);
        }
      });
    }
  });

  // Check for missing security settings
  if (envRequirements.security) {
    envRequirements.security.warnIfMissing?.forEach(variable => {
      if (!env[variable]) {
        console.log(`  ⚠️  ${variable} - Security setting missing`);
      }
    });
  }

  // Critical production checks
  if (nodeEnv === 'production') {
    console.log('\n🚨 PRODUCTION CRITICAL CHECKS:');

    // Check for production-specific issues
    if (env.API_KEY === 'your_secure_api_key_here' || 
        env.API_KEY === 'development_key' ||
        env.API_KEY === 'test_key') {
      console.log('  ❌ API_KEY - Using default/test value in production!');
    }

    if (env.SECURITY_ENABLED === 'false') {
      console.log('  ❌ SECURITY_ENABLED - Security disabled in production!');
    }

    if (!env.CORS_ALLOWED_ORIGINS || env.CORS_ALLOWED_ORIGINS === '*') {
      console.log('  ⚠️  CORS_ALLOWED_ORIGINS - Too permissive or not set');
    }

    if (parseInt(env.RATE_LIMIT_MAX) > 100) {
      console.log(`  ⚠️  RATE_LIMIT_MAX - Value ${env.RATE_LIMIT_MAX} may be too high`);
    }
  }

  // Summary
  console.log('\n📊 SUMMARY:');
  console.log(`   Total environment variables: ${Object.keys(env).length}`);
  console.log(`   Missing required: ${missingRequired.length}`);

  if (missingRequired.length > 0) {
    console.log('\n❌ VALIDATION FAILED: Missing required variables:');
    missingRequired.forEach(v => console.log(`   - ${v}`));
    process.exit(1);
  } else {
    console.log('\n✅ VALIDATION PASSED: All required variables present');

    // Additional warnings
    if (nodeEnv === 'production') {
      console.log('\n💡 PRODUCTION RECOMMENDATIONS:');
      console.log('   1. Enable HTTPS/TLS for all traffic');
      console.log('   2. Use a proper secret management system');
      console.log('   3. Implement regular key rotation');
      console.log('   4. Set up monitoring and alerting');
      console.log('   5. Regular security audits');
    }
  }
}

// Run validation
if (require.main === module) {
  validateConfiguration();
}

module.exports = {
  validateConfiguration,
  requirements,
  securityPatterns
};

